field.description:
Transparent mode identifies the workstation by source IP and does not challenge the browser. Explicit mode requires
clients to use the proxy address or PAC/WPAD. This initial standalone release enables native Kerberos/SPNEGO;
additional authentication plugins will be activated only after their engine-side validation is complete.

packagegui.custom_php_validation_command:
/* Keep the generic package editor's write_config() audit entry explicit
 * even on platform versions that lose this parsed XML value during POST. */
$pkg['addedit_string'] = 'Kontrol-ID: changed settings.';
kontrol_id_validate($_POST, $input_errors);

packagegui.custom_php_resync_config_command:
kontrol_id_resync();
if (!empty($_POST['_kontrol_id_activation_deferred'])) {
	$savemsg = 'General settings were saved. Kontrol-ID remains disabled: ' .
		$_POST['_kontrol_id_activation_deferred'] .
		' Complete Domain and Keytab, then return to General to enable the service.';
}
unset($_POST['_kontrol_id_activation_deferred']);
